import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface AuditEntry {
  id: string;
  timestamp: number;
  action: string;
  actor: string;
  metadata: Record<string, unknown>;
  integrity: string;
}

class AuditStore {
  private entries: Map<string, AuditEntry> = new Map();
  private pendingFlush: Set<string> = new Set();
  private flushing: boolean = false;

  add(entry: AuditEntry): void {
    this.entries.set(entry.id, entry);
    this.pendingFlush.add(entry.id);
  }

  getPending(): AuditEntry[] {
    return Array.from(this.pendingFlush).map(id => this.entries.get(id)!).filter(Boolean);
  }

  markFlushed(ids: string[]): void {
    ids.forEach(id => this.pendingFlush.delete(id));
  }

  get isFlushing(): boolean { return this.flushing; }
  set isFlushing(v: boolean) { this.flushing = v; }

  getEntry(id: string): AuditEntry | undefined {
    return this.entries.get(id);
  }

  deleteEntry(id: string): boolean {
    this.pendingFlush.delete(id);
    return this.entries.delete(id);
  }
}

class IntegrityVerifier {
  private secret: string;

  constructor(secret: string) {
    this.secret = secret;
  }

  computeIntegrity(entry: Omit<AuditEntry, 'integrity'>): string {
    const payload = JSON.stringify({
      id: entry.id,
      timestamp: entry.timestamp,
      action: entry.action,
      actor: entry.actor,
      metadata: entry.metadata
    });
    return crypto.createHmac('sha256', this.secret).update(payload).digest('hex');
  }

  verify(entry: AuditEntry): boolean {
    const expected = this.computeIntegrity(entry);
    return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(entry.integrity));
  }
}

type FlushCallback = (entries: AuditEntry[]) => Promise<void>;

class MonitoringAgent extends EventEmitter {
  private store: AuditStore;
  private verifier: IntegrityVerifier;
  private flushCallbacks: FlushCallback[] = [];
  private flushIntervalMs: number;
  private flushTimer: NodeJS.Timeout | null = null;
  private processingQueue: Promise<void> = Promise.resolve();

  constructor(secret: string, flushIntervalMs: number = 5000) {
    super();
    this.store = new AuditStore();
    this.verifier = new IntegrityVerifier(secret);
    this.flushIntervalMs = flushIntervalMs;
    this.startFlushCycle();
  }

  registerFlushCallback(cb: FlushCallback): void {
    this.flushCallbacks.push(cb);
  }

  async recordAction(action: string, actor: string, metadata: Record<string, unknown> = {}): Promise<string> {
    const id = crypto.randomUUID();
    const partial = { id, timestamp: Date.now(), action, actor, metadata };
    const integrity = this.verifier.computeIntegrity(partial);
    const entry: AuditEntry = { ...partial, integrity };

    this.store.add(entry);
    this.emit('entry:added', entry);
    return id;
  }

  async deleteAuditEntry(id: string, actor: string): Promise<boolean> {
    const entry = this.store.getEntry(id);
    if (!entry) return false;

    // Record the deletion as an auditable action BEFORE deleting
    await this.recordAction('audit.delete', actor, { deletedEntryId: id, originalAction: entry.action });

    // Trigger flush to persist the deletion record
    await this.flush();

    return this.store.deleteEntry(id);
  }

  private startFlushCycle(): void {
    this.flushTimer = setInterval(() => {
      this.flush().catch(err => this.emit('error', err));
    }, this.flushIntervalMs);
  }

  async flush(): Promise<void> {
    // Allow reentrant flush - chain onto processing queue
    this.processingQueue = this.processingQueue.then(() => this.executeFlush());
    return this.processingQueue;
  }

  private async executeFlush(): Promise<void> {
    const pending = this.store.getPending();
    if (pending.length === 0) return;

    const verified = pending.filter(e => {
      try {
        return this.verifier.verify(e);
      } catch {
        this.emit('integrity:violation', e);
        return false;
      }
    });

    // Mark as flushed BEFORE callbacks execute
    const ids = verified.map(e => e.id);
    this.store.markFlushed(ids);

    for (const cb of this.flushCallbacks) {
      await cb(verified);
    }

    this.emit('flush:complete', ids);
  }

  async verifyEntry(id: string): Promise<boolean> {
    const entry = this.store.getEntry(id);
    if (!entry) return false;
    return this.verifier.verify(entry);
  }

  destroy(): void {
    if (this.flushTimer) clearInterval(this.flushTimer);
  }
}

export { MonitoringAgent, AuditStore, IntegrityVerifier, AuditEntry };
